#include <Aevrynd/WorldOrigin3D.h>
#include <algorithm>
#include <cmath>
#include <limits>

namespace Aevrynd {
namespace {
bool Finite(Vec3 value){return std::isfinite(value.x)&&std::isfinite(value.y)&&std::isfinite(value.z);}
bool CheckedAdd(std::int64_t left,std::int64_t right,std::int64_t& result){if((right>0&&left>(std::numeric_limits<std::int64_t>::max)()-right)||(right<0&&left<(std::numeric_limits<std::int64_t>::min)()-right))return false;result=left+right;return true;}
bool NormalizeAxis(float& offset,std::int64_t& chunk,float chunkSize){const long double size=chunkSize,half=size*.5L,value=offset;if(!std::isfinite(double(value)))return false;const long double shift=std::floor((value+half)/size),minimum=static_cast<long double>((std::numeric_limits<std::int64_t>::min)()),maximum=static_cast<long double>((std::numeric_limits<std::int64_t>::max)());if(shift<minimum||shift>maximum)return false;const auto quotient=static_cast<std::int64_t>(shift);std::int64_t normalized{};if(!CheckedAdd(chunk,quotient,normalized))return false;const long double local=value-shift*size;if(!std::isfinite(double(local))||local<-half||local>=half||std::abs(local)>std::numeric_limits<float>::max())return false;chunk=normalized;offset=float(local);return true;}
bool LocalAxis(std::int64_t chunk,float offset,std::int64_t originChunk,float originOffset,float chunkSize,float& result){const long double chunks=static_cast<long double>(chunk)-static_cast<long double>(originChunk),value=chunks*chunkSize+static_cast<long double>(offset)-originOffset;if(!std::isfinite(double(value))||std::abs(value)>std::numeric_limits<float>::max())return false;result=float(value);return std::isfinite(result);}
}
bool NormalizeGlobalPosition3D(GlobalPosition3D& value,float chunkSize)noexcept{if(!std::isfinite(chunkSize)||chunkSize<=0||!Finite(value.offset))return false;GlobalPosition3D copy=value;if(!NormalizeAxis(copy.offset.x,copy.chunk.x,chunkSize)||!NormalizeAxis(copy.offset.y,copy.chunk.y,chunkSize)||!NormalizeAxis(copy.offset.z,copy.chunk.z,chunkSize))return false;value=copy;return true;}
bool AddGlobalPosition3D(GlobalPosition3D value,Vec3 delta,GlobalPosition3D& result,float chunkSize)noexcept{if(!Finite(delta))return false;value.offset=value.offset+delta;if(!NormalizeGlobalPosition3D(value,chunkSize))return false;result=value;return true;}
bool ToLocalPosition3D(GlobalPosition3D value,WorldOrigin3D origin,Vec3& result,float chunkSize)noexcept{if(!origin.generation||!NormalizeGlobalPosition3D(value,chunkSize)||!NormalizeGlobalPosition3D(origin.position,chunkSize))return false;Vec3 local{};if(!LocalAxis(value.chunk.x,value.offset.x,origin.position.chunk.x,origin.position.offset.x,chunkSize,local.x)||!LocalAxis(value.chunk.y,value.offset.y,origin.position.chunk.y,origin.position.offset.y,chunkSize,local.y)||!LocalAxis(value.chunk.z,value.offset.z,origin.position.chunk.z,origin.position.offset.z,chunkSize,local.z))return false;result=local;return true;}
bool ToGlobalPosition3D(Vec3 local,WorldOrigin3D origin,GlobalPosition3D& result,float chunkSize)noexcept{if(!origin.generation||!Finite(local))return false;return AddGlobalPosition3D(origin.position,local,result,chunkSize);}
WorldOriginCoordinator3D::WorldOriginCoordinator3D(WorldOrigin3D initial,float chunkSize):origin_(initial),chunkSize_(chunkSize),owner_(std::this_thread::get_id()){if(!origin_.generation||!NormalizeGlobalPosition3D(origin_.position,chunkSize_)||!std::isfinite(chunkSize_)||chunkSize_<=0){origin_={};origin_.generation=1;chunkSize_=32.f;}}
bool WorldOriginCoordinator3D::Register(IWorldOriginParticipant3D& participant){if(std::this_thread::get_id()!=owner_||pending_||std::find(participants_.begin(),participants_.end(),&participant)!=participants_.end())return false;try{participants_.push_back(&participant);return true;}catch(...){return false;}}
bool WorldOriginCoordinator3D::Unregister(IWorldOriginParticipant3D& participant)noexcept{if(std::this_thread::get_id()!=owner_||pending_)return false;const auto found=std::find(participants_.begin(),participants_.end(),&participant);if(found==participants_.end())return false;participants_.erase(found);return true;}
bool WorldOriginCoordinator3D::Request(GlobalPosition3D origin){if(std::this_thread::get_id()!=owner_||pending_||!NormalizeGlobalPosition3D(origin,chunkSize_)||origin==origin_.position)return false;requested_=origin;pending_=true;return true;}
bool WorldOriginCoordinator3D::ApplyFrameBoundary(){if(std::this_thread::get_id()!=owner_||!pending_||origin_.generation==(std::numeric_limits<std::uint64_t>::max)())return false;Vec3 delta{};if(!ToLocalPosition3D(requested_,origin_,delta,chunkSize_))return false;WorldOriginRebaseEvent3D event{origin_,{requested_,origin_.generation+1},delta};std::size_t prepared{};for(;prepared<participants_.size();++prepared)if(!participants_[prepared]->PrepareWorldOriginRebase3D(event))break;if(prepared!=participants_.size()){while(prepared)participants_[--prepared]->AbortWorldOriginRebase3D();return false;}for(auto* participant:participants_)participant->CommitWorldOriginRebase3D(event);origin_=event.current;pending_=false;++applied_;return true;}
}
